#!/usr/bin/env python3
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from linroute.cache import slug
from linroute.prompts import PROMPT_DIR, check_template, sha256_file
from linroute.relations import MAX_REL_TEMPLATES

HEADER = """\
# The prompts of every Hernandez et al. (2024) relation, AS USED.
#
# Generated by scripts/snapshot_wild_prompts.py -- edit that script, or the
# checkout it reads, not this file.
#
# `templates` is already truncated to the first max_rel_templates entries of
# the JSON's `prompt_templates`, in order, because that is what
# linroute.relations.load_relations puts in front of the model and what a
# cache's `rel_templates` records.  `prompt_templates_zs` is copied whole.
# `source_sha256` is the hash of the JSON these strings were read from;
# linroute.prompts.wild_relation refuses to hand out prompts whose source file
# no longer hashes to it, so a re-pulled or hand-edited checkout is caught
# before it can produce a mislabelled cache.
#
# The samples are NOT here.  They are data, they are large, and they stay in
# the JSONs; the loader takes samples from the JSON and prompts from this file.
"""

def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    p = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    p.add_argument(
        "--relations-dir",
        required=True,
        help="the Hernandez checkout's data directory (its */*.json)",
    )
    p.add_argument(
        "--out",
        default=str(PROMPT_DIR / "wild.yaml"),
        help="where to write the snapshot (default: data/prompts/wild.yaml)",
    )
    return p.parse_args(argv)

def entries(root: Path) -> list[dict]:
    out = []
    for path in sorted(root.glob("*/*.json")):
        blob = json.loads(path.read_text(encoding="utf-8"))
        name = blob["name"]
        templates = list(blob["prompt_templates"])[:MAX_REL_TEMPLATES]
        zs = list(blob.get("prompt_templates_zs") or [])
        for i, t in enumerate(templates):
            check_template(t, f"{path}:prompt_templates[{i}]")
        for i, t in enumerate(zs):
            check_template(t, f"{path}:prompt_templates_zs[{i}]")
        out.append(
            {
                "name": name,
                "slug": slug(name),
                "relation_type": blob["properties"]["relation_type"],
                "source_file": path.relative_to(root).as_posix(),
                "source_sha256": sha256_file(path),
                "templates": templates,
                "prompt_templates_zs": zs,
            }
        )
    names = [e["name"] for e in out]
    if len(set(names)) != len(names):
        raise SystemExit(f"duplicate relation names in {root}")
    return sorted(out, key=lambda e: e["name"])

def render(records: list[dict]) -> str:
    q = json.dumps
    lines = [HEADER, "schema: linroute/prompts/wild/1",
             f"max_rel_templates: {MAX_REL_TEMPLATES}", "", "relations:"]
    for r in records:
        lines.append(f"  - name: {q(r['name'])}")
        lines.append(f"    slug: {q(r['slug'])}")
        lines.append(f"    relation_type: {q(r['relation_type'])}")
        lines.append(f"    source_file: {q(r['source_file'])}")
        lines.append(f"    source_sha256: {q(r['source_sha256'])}")
        for key in ("templates", "prompt_templates_zs"):
            if not r[key]:
                lines.append(f"    {key}: []")
                continue
            lines.append(f"    {key}:")
            lines.extend(f"      - {q(t)}" for t in r[key])
    return "\n".join(lines) + "\n"

def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    root = Path(args.relations_dir).expanduser()
    if not root.is_dir():
        raise SystemExit(f"--relations-dir {root} is not a directory")
    records = entries(root)
    if not records:
        raise SystemExit(f"no relation JSONs under {root}/*/*.json")
    out = Path(args.out)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(render(records), encoding="utf-8")
    print(f"{len(records)} relations -> {out}")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
